00053 // Write a multibyte encoded uint64_t
00054 //
00055 static void write_multibyte_bytes(BitstreamPacker &b, uint64_t value, bool more) {
00056     if (value > 0x7f)
00057         write_multibyte_bytes(b, value >> 7, true);
00058 
00059     b.u(1, more ? 1 : 0, "mb-more");
00060     b.u(7, value & 0x7f, "mb-bits");
00061 }
00062 
00063 static void write_multibyte(BitstreamPacker &b, uint64_t value, const std::string &label) {
00064     BitstreamPacker::ScopedContextLabel l(b, label);
00065     write_multibyte_bytes(b, value, false);
00066 }
