00080 //
00081 //
00082 Packet Serializer::emit(const SignaledConfiguration &configuration, unsigned block_mask,
00083                         const Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS]) {
00084     BitstreamPacker bitstream;
00085 
00086     for (unsigned b = SyntaxBlock_Sequence; b <= SyntaxBlock_Filler; b <<= 1) {
00087         if (block_mask & b) {
00088             Packet p = emit_block(configuration, b, symbols);
00089             bitstream.bytes(p);
00090         }
00091     }
00092 
00093     return bitstream.finish();
00094 }
00095 
00096 Packet Serializer::emit_block(const SignaledConfiguration &configuration, unsigned block,
00097                               const Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS]) {
00098 
00099     const unsigned num_residual_layers = configuration.global_configuration.num_residual_layers;
00100 
00101     // Emit block into a packet
00102     //
00103     BitstreamPacker contents_bitstream;
00104 
00105     unsigned payload_type{};
00106 
00107     switch (block) {
00108     case SyntaxBlock_Sequence:
00109         emit_sequence_configuration(configuration.sequence_configuration, contents_bitstream);
00110         payload_type = 0;
00111         break;
00112 
00113     case SyntaxBlock_Global:
00114         emit_global_configuration(configuration.global_configuration, contents_bitstream);
00115         payload_type = 1;
00116         break;
00117 
00118     case SyntaxBlock_Picture:
00119         emit_picture_configuration(configuration.picture_configuration, contents_bitstream, num_residual_layers);
00120         payload_type = 2;
00121         break;
00122 
00123     case SyntaxBlock_EncodedData:
00124         emit_encoded_data(configuration, contents_bitstream, symbols, num_residual_layers);
00125         payload_type = 3;
00126         break;
00127 
00128     case SyntaxBlock_EncodedData_Tiled:
00129         emit_encoded_data_tiled(configuration, contents_bitstream, symbols, num_residual_layers);
00130         payload_type = 4;
00131         break;
00132 
00133     case SyntaxBlock_Additional_Info:
00134         INFO("emit_additional_info");
00135         emit_additional_info(configuration.additional_info, contents_bitstream);
00136         payload_type = 5;
00137         break;
00138 
00139         /***
00140     case SyntaxBlock_Additional_Info:
00141         emit_additional_info(contents_bitstream);
00142         payload_type = 6;
00143         break;
00144         ***/
00145 
00146     case SyntaxBlock_Filler:
00147         emit_filler(contents_bitstream, 0); // XXXX pass filler size
00148         payload_type = 6;
00149         break;
00150 
00151     default:
00152         CHECK(0);
00153     }
00154 
00155     Packet contents = contents_bitstream.finish();
00156 
00157     BitstreamPacker block_bitstream;
00158 
00159     // Block header
00160     unsigned payload_size_type = 0;
00161     switch (contents.size()) {
00162     case 0:
00163         payload_size_type = 0;
00164         break;
00165     case 1:
00166         payload_size_type = 1;
00167         break;
00168     case 2:
00169         payload_size_type = 2;
00170         break;
00171     case 3:
00172         payload_size_type = 3;
00173         break;
00174     case 4:
00175         payload_size_type = 4;
00176         break;
00177     case 5:
00178         payload_size_type = 5;
00179         break;
00180     default:
00181         payload_size_type = 7;
00182         break;
00183     }
00184 
00185     block_bitstream.u(3, payload_size_type, "payload_size_type");
00186     block_bitstream.u(5, payload_type, "payload_type");
00187 
00188     if (payload_size_type == 7)
00189         write_multibyte(block_bitstream, contents.size(), "payload_byte_size");
00190 
00191     // Block contents
00192     block_bitstream.bytes(PacketView(contents));
00193 
00194     return block_bitstream.finish();
00195 }
