00197 // Write each configuration
00198 //
00199 void Serializer::emit_sequence_configuration(const SequenceConfiguration &sequence_configuration, BitstreamPacker &b) {
00200 #if BITSTREAM_DEBUG
00201     fprintf(goBits, "@@@@ @@@@ sequence_config >>>> \n");
00202     fflush(goBits);
00203 #endif
00204 
00205     BitstreamPacker::ScopedContextLabel label(b, "sequence_config");
00206 
00207     switch (sequence_configuration.profile_idc) {
00208     case Profile_Main:
00209         b.u(4, 0, "profile_idc");
00210         break;
00211     case Profile_Main444:
00212         b.u(4, 1, "profile_idc");
00213         break;
00214     default:
00215         CHECK(0);
00216     }
00217     b.u(4, sequence_configuration.level_idc, "level_idc");
00218     b.u(2, sequence_configuration.sublevel_idc, "sublevel_idc");
00219     b.u(1, sequence_configuration.conformance_window, "conformance_window");
00220     b.u(5, 0, "reserved");
00221     if (sequence_configuration.profile_idc == 15 || sequence_configuration.level_idc == 15) {
00222         b.u(3, sequence_configuration.extended_profile_idc, "extended_profile_idc");
00223         b.u(4, sequence_configuration.extended_level_idc, "extended_level_idc");
00224         b.u(1, 0, "reserved");
00225     }
00226     if (sequence_configuration.conformance_window) {
00227         write_multibyte(b, sequence_configuration.conf_win_left_offset, "conf_win_left_offset");
00228         write_multibyte(b, sequence_configuration.conf_win_right_offset, "conf_win_right_offset");
00229         write_multibyte(b, sequence_configuration.conf_win_top_offset, "conf_win_top_offset");
00230         write_multibyte(b, sequence_configuration.conf_win_bottom_offset, "conf_win_bottom_offset");
00231     }
00232 
00233 #if BITSTREAM_DEBUG
00234     fprintf(goBits, "@@@@ @@@@ sequence_config <<<< \n");
00235     fflush(goBits);
00236 #endif
00237 }
