00239 void Serializer::emit_global_configuration(const GlobalConfiguration &global_configuration, BitstreamPacker &b) {
00240 #if BITSTREAM_DEBUG
00241     fprintf(goBits, "@@@@ @@@@ global_config >>>> \n");
00242     fflush(goBits);
00243 #endif
00244 
00245     BitstreamPacker::ScopedContextLabel label(b, "global_config");
00246 
00247     switch (global_configuration.num_processed_planes) {
00248     case 1:
00249         b.u(1, 0, "processed_planes_type");
00250         break;
00251     case 3:
00252         b.u(1, 1, "processed_planes_type");
00253         break;
00254     default:
00255         CHECK(0);
00256     }
00257 
00258     unsigned resolution_type = 0;
00259     for (resolution_type = 0; resolution_type < ARRAY_SIZE(resolution_table); ++resolution_type)
00260         if (global_configuration.resolution_width == resolution_table[resolution_type][0] &&
00261             global_configuration.resolution_height == resolution_table[resolution_type][1])
00262             break;
00263     if (resolution_type < ARRAY_SIZE(resolution_table)) {
00264         b.u(6, resolution_type, "resolution_type");
00265     } else {
00266         resolution_type = 63;
00267         b.u(6, 63, "resolution_type");
00268     }
00269 
00270     switch (global_configuration.transform_block_size) {
00271     case 2:
00272         b.u(1, 0, "transform_type");
00273         break;
00274     case 4:
00275         b.u(1, 1, "transform_type");
00276         break;
00277     default:
00278         CHECK(0);
00279     }
00280 
00281     switch (global_configuration.colourspace) {
00282     case Colourspace_Y:
00283         b.u(2, 0, "chroma_sampling_type");
00284         break;
00285     case Colourspace_YUV420:
00286         b.u(2, 1, "chroma_sampling_type");
00287         break;
00288     case Colourspace_YUV422:
00289         b.u(2, 2, "chroma_sampling_type");
00290         break;
00291     case Colourspace_YUV444:
00292         b.u(2, 3, "chroma_sampling_type");
00293         break;
00294     default:
00295         CHECK(0);
00296     }
00297 
00298     switch (global_configuration.base_depth) {
00299     case 8:
00300         b.u(2, 0, "base_depth_type");
00301         break;
00302     case 10:
00303         b.u(2, 1, "base_depth_type");
00304         break;
00305     case 12:
00306         b.u(2, 2, "base_depth_type");
00307         break;
00308     case 14:
00309         b.u(2, 3, "base_depth_type");
00310         break;
00311     default:
00312         CHECK(0);
00313     }
00314 
00315     switch (global_configuration.enhancement_depth) {
00316     case 8:
00317         b.u(2, 0, "enhancement_depth_type");
00318         break;
00319     case 10:
00320         b.u(2, 1, "enhancement_depth_type");
00321         break;
00322     case 12:
00323         b.u(2, 2, "enhancement_depth_type");
00324         break;
00325     case 14:
00326         b.u(2, 3, "enhancement_depth_type");
00327         break;
00328     default:
00329         CHECK(0);
00330     }
00331 
00332     if (global_configuration.temporal_step_width_modifier == 48)
00333         b.u(1, 0, "temporal_step_width_modifier_signalled");
00334     else
00335         b.u(1, 1, "temporal_step_width_modifier_signalled");
00336 
00337     b.u(1, global_configuration.predicted_residual_enabled, "predicted_residual_mode");
00338     b.u(1, global_configuration.temporal_tile_intra_signalling_enabled, "temporal_tile_intra_signalling_enabled");
00339     b.u(1, global_configuration.temporal_enabled, "temporal_enabled");
00340 
00341     switch (global_configuration.upsample) {
00342     case Upsample_Nearest:
00343         b.u(3, 0, "upsample_type");
00344         break;
00345     case Upsample_Linear:
00346         b.u(3, 1, "upsample_type");
00347         break;
00348     case Upsample_Cubic:
00349         b.u(3, 2, "upsample_type");
00350         break;
00351     case Upsample_ModifiedCubic:
00352         b.u(3, 3, "upsample_type");
00353         break;
00354     case Upsample_AdaptiveCubic:
00355         b.u(3, 4, "upsample_type");
00356         break;
00357     default:
00358         CHECK(0);
00359     }
00360 
00361     if (global_configuration.level_1_filtering_first_coefficient == 0 &&
00362         global_configuration.level_1_filtering_second_coefficient == 0)
00363         b.u(1, 0, "level_1_filtering_signalled");
00364     else
00365         b.u(1, 1, "level_1_filtering_signalled");
00366 
00367     switch (global_configuration.scaling_mode[LOQ_LEVEL_1]) {
00368     case ScalingMode_None:
00369         b.u(2, 0, "scaling_mode_level1");
00370         break;
00371     case ScalingMode_1D:
00372         b.u(2, 1, "scaling_mode_level1");
00373         break;
00374     case ScalingMode_2D:
00375         b.u(2, 2, "scaling_mode_level1");
00376         break;
00377     default:
00378         CHECK(0);
00379     }
00380 
00381     switch (global_configuration.scaling_mode[LOQ_LEVEL_2]) {
00382     case ScalingMode_None:
00383         b.u(2, 0, "scaling_mode_level2");
00384         break;
00385     case ScalingMode_1D:
00386         b.u(2, 1, "scaling_mode_level2");
00387         break;
00388     case ScalingMode_2D:
00389         b.u(2, 2, "scaling_mode_level2");
00390         break;
00391     default:
00392         CHECK(0);
00393     }
00394 
00395     switch (global_configuration.tile_dimensions_type) {
00396     case TileDimensions_None:
00397         b.u(2, 0, "tile_dimensions_type");
00398         break;
00399     case TileDimensions_512x256:
00400         b.u(2, 1, "tile_dimensions_type");
00401         break;
00402     case TileDimensions_1024x512:
00403         b.u(2, 2, "tile_dimensions_type");
00404         break;
00405     case TileDimensions_Custom:
00406         b.u(2, 3, "tile_dimensions_type");
00407         break;
00408     default:
00409         CHECK(0);
00410     }
00411 
00412     switch (global_configuration.user_data_enabled) {
00413     case UserData_None:
00414         b.u(2, 0, "user_data_enabled");
00415         break;
00416     case UserData_2bits:
00417         b.u(2, 1, "user_data_enabled");
00418         break;
00419     case UserData_6bits:
00420         b.u(2, 2, "user_data_enabled");
00421         break;
00422     default:
00423         CHECK(0);
00424     }
00425 
00426     b.u(1, global_configuration.level1_depth_flag, "level1_depth_flags");
00427 
00428     if (global_configuration.chroma_step_width_multiplier != 64)
00429         b.u(1, 1, "chroma_step_width_flag");
00430     else
00431         b.u(1, 0, "chroma_step_width_flag");
00432 
00433     if (global_configuration.num_processed_planes != 1) {
00434         CHECK(global_configuration.num_processed_planes == 3);
00435         b.u(4, 1, "planes_type");
00436         b.u(4, 0, "reserved");
00437     }
00438 
00439     if (global_configuration.temporal_step_width_modifier != 48)
00440         b.u(8, global_configuration.temporal_step_width_modifier, "temporal_step_width_modifier");
00441 
00442     if (global_configuration.upsample == Upsample_AdaptiveCubic) {
00443         b.u(16, global_configuration.upsampling_coefficients[0], "upsampling_coefficients[0]");
00444         b.u(16, global_configuration.upsampling_coefficients[1], "upsampling_coefficients[1]");
00445         b.u(16, global_configuration.upsampling_coefficients[2], "upsampling_coefficients[2]");
00446         b.u(16, global_configuration.upsampling_coefficients[3], "upsampling_coefficients[3]");
00447     }
00448 
00449     if (global_configuration.level_1_filtering_first_coefficient != 0 ||
00450         global_configuration.level_1_filtering_second_coefficient != 0) {
00451         b.u(4, global_configuration.level_1_filtering_first_coefficient, "level_1_filtering_first_coefficient");
00452         b.u(4, global_configuration.level_1_filtering_second_coefficient, "level_1_filtering_second_coefficient");
00453     }
00454 
00455     if (global_configuration.tile_dimensions_type != TileDimensions_None) {
00456         switch (global_configuration.tile_dimensions_type) {
00457         case TileDimensions_512x256:
00458             CHECK(global_configuration.tile_width == 512);
00459             CHECK(global_configuration.tile_height == 256);
00460             break;
00461         case TileDimensions_1024x512:
00462             CHECK(global_configuration.tile_width == 1024);
00463             CHECK(global_configuration.tile_height == 512);
00464             break;
00465         case TileDimensions_Custom:
00466             b.u(16, global_configuration.tile_width, "custom_tile_width");
00467             b.u(16, global_configuration.tile_height, "custom_tile_height");
00468             break;
00469         default:
00470             CHECK(0);
00471         }
00472         b.u(5, 0, "reserved");
00473         b.u(1, global_configuration.compression_type_entropy_enabled_per_tile, "compression_type_entropy_enabled_per_tile");
00474         switch (global_configuration.compression_type_size_per_tile) {
00475         case CompressionType_None:
00476             b.u(2, 0, "compression_type_size_per_tile");
00477             break;
00478         case CompressionType_Prefix:
00479             b.u(2, 1, "compression_type_size_per_tile");
00480             break;
00481         case CompressionType_Prefix_OnDiff:
00482             b.u(2, 2, "compression_type_size_per_tile");
00483             break;
00484         default:
00485             CHECK(0);
00486         }
00487     }
00488 
00489     if (resolution_type == 63) {
00490         b.u(16, global_configuration.resolution_width, "resolution_width");
00491         b.u(16, global_configuration.resolution_height, "resolution_height");
00492     }
00493 
00494     if (global_configuration.chroma_step_width_multiplier != 64)
00495         b.u(8, global_configuration.chroma_step_width_multiplier, "chroma_step_width_multiplier");
00496 
00497 #if BITSTREAM_DEBUG
00498     fprintf(goBits, "@@@@ @@@@ global_config <<<< \n");
00499     fflush(goBits);
00500 #endif
00501 }
