00503 void Serializer::emit_picture_configuration(const PictureConfiguration &picture_configuration, BitstreamPacker &b,
00504                                             unsigned num_layers) {
00505 #if BITSTREAM_DEBUG
00506     fprintf(goBits, "@@@@ @@@@ picture_config >>>> \n");
00507     fflush(goBits);
00508 #endif
00509 
00510     BitstreamPacker::ScopedContextLabel label(b, "picture_config");
00511 
00512     b.u(1, !picture_configuration.enhancement_enabled, "no_enhancement_bit");
00513 
00514     if (picture_configuration.enhancement_enabled) {
00515         switch (picture_configuration.quant_matrix_mode) {
00516         case QuantMatrix_BothPrevious:
00517             b.u(3, 0, "quant_matrix_mode");
00518             break;
00519         case QuantMatrix_BothDefault:
00520             b.u(3, 1, "quant_matrix_mode");
00521             break;
00522         case QuantMatrix_SameAndCustom:
00523             b.u(3, 2, "quant_matrix_mode");
00524             break;
00525         case QuantMatrix_Level2CustomLevel1Default:
00526             b.u(3, 3, "quant_matrix_mode");
00527             break;
00528         case QuantMatrix_Level2DefaultLevel1Custom:
00529             b.u(3, 4, "quant_matrix_mode");
00530             break;
00531         case QuantMatrix_DifferentAndCustom:
00532             b.u(3, 5, "quant_matrix_mode");
00533             break;
00534         default:
00535             CHECK(0);
00536         }
00537         b.u(1, picture_configuration.dequant_offset_signalled, "dequant_offset_signalled");
00538         switch (picture_configuration.picture_type) {
00539         case PictureType_Frame:
00540             b.u(1, 0, "picture_type");
00541             break;
00542         case PictureType_Field:
00543             b.u(1, 1, "picture_type");
00544             break;
00545         default:
00546             CHECK(0);
00547         }
00548         b.u(1, picture_configuration.temporal_refresh, "temporal_refresh");
00549         if (picture_configuration.step_width_loq[LOQ_LEVEL_1] == MAX_STEP_WIDTH)
00550             b.u(1, 0, "step_width_level1_enabled");
00551         else
00552             b.u(1, 1, "step_width_level1_enabled");
00553         b.u(15, picture_configuration.step_width_loq[LOQ_LEVEL_2], "step_width_level2");
00554         b.u(1, picture_configuration.dithering_control, "dithering_control");
00555     } else {
00556         b.u(4, 0, "reserved");
00557         switch (picture_configuration.picture_type) {
00558         case PictureType_Frame:
00559             b.u(1, 0, "picture_type");
00560             break;
00561         case PictureType_Field:
00562             b.u(1, 1, "picture_type");
00563             break;
00564         default:
00565             CHECK(0);
00566         }
00567         b.u(1, picture_configuration.temporal_refresh, "temporal_refresh");
00568         b.u(1, picture_configuration.temporal_signalling_present, "temporal_signalling_present");
00569     }
00570 
00571     if (picture_configuration.picture_type == PictureType_Field) {
00572         switch (picture_configuration.field_type) {
00573         case FieldType_Top:
00574             b.u(1, 0, "field_type");
00575             break;
00576         case FieldType_Bottom:
00577             b.u(1, 1, "field_type");
00578             break;
00579         default:
00580             CHECK(0);
00581         }
00582         b.u(7, 0, "reserved");
00583     }
00584 
00585     if (picture_configuration.step_width_loq[LOQ_LEVEL_1] != MAX_STEP_WIDTH) {
00586         b.u(15, picture_configuration.step_width_loq[LOQ_LEVEL_1], "step_width_level1");
00587         b.u(1, picture_configuration.level_1_filtering_enabled, "level_1_filtering_enabled");
00588     }
00589 
00590     if (picture_configuration.quant_matrix_mode == QuantMatrix_SameAndCustom ||
00591         picture_configuration.quant_matrix_mode == QuantMatrix_Level2CustomLevel1Default ||
00592         picture_configuration.quant_matrix_mode == QuantMatrix_DifferentAndCustom) {
00593         for (unsigned layerIndex = 0; layerIndex < num_layers; layerIndex++)
00594             b.u(8, picture_configuration.qm_coefficient_2[layerIndex], "qm_coefficient_0");
00595     }
00596     if (picture_configuration.quant_matrix_mode == QuantMatrix_Level2DefaultLevel1Custom ||
00597         picture_configuration.quant_matrix_mode == QuantMatrix_DifferentAndCustom) {
00598         for (unsigned layerIndex = 0; layerIndex < num_layers; layerIndex++)
00599             b.u(8, picture_configuration.qm_coefficient_1[layerIndex], "qm_coefficient_1");
00600     }
00601 
00602     if (picture_configuration.dequant_offset_signalled) {
00603         switch (picture_configuration.dequant_offset_mode) {
00604         case DequantOffset_Default:
00605             b.u(1, 0, "dequant_offset_mode");
00606             break;
00607         case DequantOffset_ConstOffset:
00608             b.u(1, 1, "dequant_offset_mode");
00609             break;
00610         default:
00611             CHECK(0);
00612         }
00613         b.u(7, picture_configuration.dequant_offset, "dequant_offset");
00614     }
00615 
00616     if (picture_configuration.dithering_control) {
00617         switch (picture_configuration.dithering_type) {
00618         case Dithering_None:
00619             b.u(2, 0, "dithering_type");
00620             break;
00621         case Dithering_Uniform:
00622         case Dithering_UniformFixed:
00623             b.u(2, 1, "dithering_type");
00624             break;
00625         default:
00626             CHECK(0);
00627         }
00628         b.u(1, 0, "reserved");
00629         if (picture_configuration.dithering_type != Dithering_None)
00630             b.u(5, picture_configuration.dithering_strength, "dithering_strength");
00631         else
00632             b.u(5, 0, "reserved");
00633     }
00634 #if BITSTREAM_DEBUG
00635     fprintf(goBits, "@@@@ @@@@ picture_config <<<< \n");
00636     fflush(goBits);
00637 #endif
00638 }
00639 
00640 // Return whether temporal layer is enabled
00641 //
00642 static unsigned temporal_layer_(const SignaledConfiguration &signaled_configuration, unsigned loq) {
00643     if (loq == LOQ_LEVEL_2 && signaled_configuration.picture_configuration.temporal_signalling_present)
00644         return 1;
00645     else
00646         return 0;
00647 }
00648 
00649 // Number of encoded layers in bitstream - residual + temporal
00650 static unsigned total_layers(const SignaledConfiguration &configuration, unsigned plane, unsigned loq) {
00651     return configuration.global_configuration.num_residual_layers +
00652            ((loq == LOQ_LEVEL_2 && configuration.picture_configuration.temporal_signalling_present) ? 1 : 0);
00653 }
00654 
00655 static unsigned first_layer(const SignaledConfiguration &configuration) {
00656     if (configuration.picture_configuration.enhancement_enabled)
00657         return 0;
00658     else
00659         return configuration.global_configuration.num_residual_layers;
00660 }
00661 
00662 static bool is_temporal_layer(const SignaledConfiguration &configuration, unsigned plane, unsigned loq, unsigned layer) {
00663     return layer == configuration.global_configuration.num_residual_layers;
00664 }
00665 
00666 void Serializer::emit_encoded_data(const SignaledConfiguration &signaled_configuration, BitstreamPacker &b,
00667                                    const Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS], unsigned num_layers) {
00668     CHECK(signaled_configuration.global_configuration.tile_dimensions_type == TileDimensions_None);
00669 
00670 #if BITSTREAM_DEBUG
00671     fprintf(goBits, "@@@@ @@@@ encoded_data >>>> \n");
00672     fflush(goBits);
00673 #endif
00674     // Entropy code the layers
00675     bool entropy_enabled[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS] = {false};
00676     bool rle_only[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS] = {false};
00677     Packet data[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS];
00678 
00679     for (unsigned plane = 0; plane < signaled_configuration.global_configuration.num_processed_planes; ++plane) {
00680         for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00681             for (unsigned layer = first_layer(signaled_configuration); layer < total_layers(signaled_configuration, plane, loq);
00682                  ++layer) {
00683                 // Entropy code symbols
00684                 EncodedChunk e;
00685                 if (!is_temporal_layer(signaled_configuration, plane, loq, layer)) {
00686                     const bool use_tiled_encoding_order = signaled_configuration.global_configuration.temporal_enabled ||
00687                                                           signaled_configuration.global_configuration.tile_dimensions_type > 0;
00688                     if (use_tiled_encoding_order) {
00689                         e = EntropyEncoderResidualsTiled().process(
00690                             symbols[plane][loq][layer], signaled_configuration.global_configuration.transform_block_size);
00691                     } else {
00692                         e = EntropyEncoderResiduals().process(symbols[plane][loq][layer]);
00693                     }
00694 
00695                 } else {
00696                     e = EntropyEncoderTemporal().process(
00697                         symbols[plane][loq][layer], signaled_configuration.global_configuration.transform_block_size,
00698                         signaled_configuration.global_configuration.temporal_tile_intra_signalling_enabled);
00699                 }
00700                 if (!e.empty()) {
00701                     entropy_enabled[plane][loq][layer] = true;
00702 
00703                     // Choose smaller of prefix coded vs. raw
00704                     if (e.prefix.size() > e.raw.size()) {
00705                         rle_only[plane][loq][layer] = true;
00706                         data[plane][loq][layer] = e.raw;
00707                     } else {
00708                         rle_only[plane][loq][layer] = false;
00709                         data[plane][loq][layer] = e.prefix;
00710                     }
00711                 }
00712             }
00713         }
00714     }
00715 
00716     // Emit flags
00717     BitstreamPacker::ScopedContextLabel label(b, "encoded_data");
00718 
00719     for (unsigned plane = 0; plane < signaled_configuration.global_configuration.num_processed_planes; ++plane) {
00720         if (signaled_configuration.picture_configuration.enhancement_enabled) {
00721             for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00722                 for (unsigned layer = 0; layer < num_layers; ++layer) {
00723                     b.u(1, entropy_enabled[plane][loq][layer], "entropy_enabled");
00724                     b.u(1, rle_only[plane][loq][layer], "rle_only");
00725                 }
00726             }
00727         }
00728         if (temporal_layer_(signaled_configuration, LOQ_LEVEL_2)) {
00729             b.u(1, entropy_enabled[plane][LOQ_LEVEL_2][num_layers], "entropy_enabled");
00730             b.u(1, rle_only[plane][LOQ_LEVEL_2][num_layers], "rle_only");
00731         }
00732     }
00733 
00734     // Byte alignment
00735 #if defined __OPT_MODULO__
00736     while ((b.bit_offset() & 0x07))
00737 #else
00738     while ((b.bit_offset() % 8 != 0))
00739 #endif
00740         b.u(1, 0, "alignment");
00741 
00742     // Emit surfaces
00743     for (unsigned plane = 0; plane < signaled_configuration.global_configuration.num_processed_planes; ++plane) {
00744         for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00745 
00746             const unsigned n = num_layers + temporal_layer_(signaled_configuration, loq);
00747 
00748             for (unsigned layer = 0; layer < n; ++layer) {
00749                 BitstreamPacker::ScopedContextLabel label(b, format("surface[%d][%d][%d]", plane, loq, layer));
00750                 if (entropy_enabled[plane][loq][layer]) {
00751                     write_multibyte(b, data[plane][loq][layer].size(), "data_size");
00752                     b.bytes(data[plane][loq][layer]);
00753                 }
00754             }
00755         }
00756     }
00757 
00758 #if BITSTREAM_DEBUG
00759     fprintf(goBits, "@@@@ @@@@ encoded_data <<<< \n");
00760     fflush(goBits);
00761 #endif
00762 }
00763 
00764 void Serializer::emit_encoded_data_tiled(const SignaledConfiguration &signaled_configuration, BitstreamPacker &b,
00765                                          const Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS], unsigned num_layers) {
00766 
00767     CHECK(signaled_configuration.global_configuration.tile_dimensions_type != TileDimensions_None);
00768 
00769     Dimensions dimensions;
00770     dimensions.set(signaled_configuration,
00771                    signaled_configuration.global_configuration.resolution_width,
00772                    signaled_configuration.global_configuration.resolution_height);
00773 
00774 #if BITSTREAM_DEBUG
00775     fprintf(goBits, "@@@@ @@@@ encoded_data_tiled >>>> \n");
00776     fflush(goBits);
00777 #endif
00778 
00779     // Accumulated flags and data
00780     std::vector<bool> rle_only;        // Per layer
00781     std::vector<bool> entropy_enabled; // Per tile
00782     std::vector<Packet> chunks;        // Per tile
00783 
00784     unsigned num_tiles[MAX_NUM_PLANES][MAX_NUM_LOQS] = {0};
00785 
00786     // Entropy code the tiles in each layer
00787     for (unsigned plane = 0; plane < signaled_configuration.global_configuration.num_processed_planes; ++plane) {
00788         for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00789 
00790             // All tile dimensions are in terms of transform blocks
00791             const unsigned tile_width = dimensions.tile_width(plane, loq);
00792             const unsigned tile_height = dimensions.tile_height(plane, loq);
00793 
00794             // Figure out tile breakdown for this level
00795             const unsigned width = symbols[plane][loq][0].width();
00796             const unsigned height = symbols[plane][loq][0].height();
00797 
00798             const unsigned tiles_x = (width + tile_width - 1) / tile_width;
00799             const unsigned tiles_y = (height + tile_height - 1) / tile_height;
00800 
00801             num_tiles[plane][loq] = tiles_x * tiles_y;
00802 
00803             for (unsigned layer = first_layer(signaled_configuration); layer < total_layers(signaled_configuration, plane, loq);
00804                  ++layer) {
00805 
00806                 std::vector<EncodedChunk> encoded_chunks;
00807                 unsigned layer_raw_sizes = 0;
00808                 unsigned layer_prefix_sizes = 0;
00809 
00810                 // For each tile ...
00811                 for (unsigned ty = 0; ty < tiles_y; ++ty) {
00812                     for (unsigned tx = 0; tx < tiles_x; ++tx) {
00813                         // Extract tile
00814                         const unsigned tx0 = tx * tile_width;
00815                         const unsigned ty0 = ty * tile_height;
00816                         const unsigned tx1 = std::min((tx + 1) * tile_width, width);
00817                         const unsigned ty1 = std::min((ty + 1) * tile_height, height);
00818 
00819                         // Entropy code (raw & prefix)
00820                         if (!is_temporal_layer(signaled_configuration, plane, loq, layer)) {
00821                             Surface tile_symbols = CropResiduals().process(symbols[plane][loq][layer], tx0, ty0, tx1, ty1);
00822                             encoded_chunks.push_back(EntropyEncoderResidualsTiled().process(
00823                                 tile_symbols, signaled_configuration.global_configuration.transform_block_size));
00824                         } else {
00825                             Surface tile_symbols = CropTemporal().process(symbols[plane][loq][layer], tx0, ty0, tx1, ty1);
00826                             encoded_chunks.push_back(EntropyEncoderTemporal().process(
00827                                 tile_symbols, signaled_configuration.global_configuration.transform_block_size,
00828                                 signaled_configuration.global_configuration.temporal_tile_intra_signalling_enabled));
00829                         }
00830                         // Accumalate raw/prefix sizes for each layer
00831                         layer_raw_sizes += encoded_chunks.back().raw.size();
00832                         layer_prefix_sizes += encoded_chunks.back().prefix.size();
00833 
00834                         // Accumalate entropy_enabled for each tile
00835                         CHECK((encoded_chunks.back().raw.size() == 0) == (encoded_chunks.back().prefix.size() == 0));
00836                         entropy_enabled.push_back(encoded_chunks.back().raw.size() > 0);
00837                     }
00838                 }
00839                 // Decide rle_only for layer based on accumulated sizes
00840                 const bool r = layer_raw_sizes < layer_prefix_sizes;
00841                 rle_only.push_back(r);
00842                 // Accumulate chosen packets
00843                 for (auto ec : encoded_chunks)
00844                     chunks.push_back(r ? ec.raw : ec.prefix);
00845             }
00846         }
00847     }
00848 
00849     CHECK(chunks.size() == entropy_enabled.size());
00850 
00851     BitstreamPacker::ScopedContextLabel label(b, "encoded_data_tiled");
00852 
00853     for (auto r : rle_only)
00854         b.u(1, r, "rle_only");
00855 
00856         // Byte alignment
00857 #if defined __OPT_MODULO__
00858     while ((b.bit_offset() & 0x07))
00859 #else
00860     while ((b.bit_offset() % 8 != 0))
00861 #endif
00862         b.u(1, 0, "alignment");
00863 
00864     // Emit per tile entropy_enabled
00865     if (!signaled_configuration.global_configuration.compression_type_entropy_enabled_per_tile) {
00866         // Don't compress entropy_enabled flags
00867         for (auto r : entropy_enabled)
00868             b.u(1, r, "entropy_enabled");
00869     } else {
00870         // Prefix code the entropy_enabled flags
00871         const Surface ee = Surface::build_from<uint8_t>()
00872                                .generate(static_cast<unsigned>(entropy_enabled.size()), 1,
00873                                          [&](unsigned x, unsigned y) -> uint8_t { return entropy_enabled[x]; })
00874                                .finish();
00875         b.bytes(EntropyEncoderFlags().process(ee).raw);
00876     }
00877 
00878     // Byte alignment
00879 #if defined __OPT_MODULO__
00880     while ((b.bit_offset() & 0x07))
00881 #else
00882     while ((b.bit_offset() % 8 != 0))
00883 #endif
00884         b.u(1, 0, "alignment");
00885 
00886     if (signaled_configuration.global_configuration.compression_type_size_per_tile == CompressionType_None) {
00887         // Don't compress tile sizes
00888         for (unsigned c = 0; c < chunks.size(); ++c) {
00889             if (entropy_enabled[c]) {
00890                 CHECK(chunks[c].size() > 0);
00891                 write_multibyte(b, chunks[c].size(), "data_size");
00892                 b.bytes(chunks[c]);
00893             }
00894         }
00895     } else {
00896         // Prefix code each layer's tile sizes
00897         unsigned idx = 0;
00898         for (unsigned plane = 0; plane < signaled_configuration.global_configuration.num_processed_planes; ++plane) {
00899             for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00900                 for (unsigned layer = first_layer(signaled_configuration); layer < total_layers(signaled_configuration, plane, loq);
00901                      ++layer) {
00902 
00903                     // Does any tile contain data?
00904                     bool any_tile_enabled = false;
00905                     for (unsigned x = 0; x < num_tiles[plane][loq]; x++) {
00906                         if (entropy_enabled[idx + x]) {
00907                             any_tile_enabled = true;
00908                             break;
00909                         }
00910                     }
00911 
00912                     if (any_tile_enabled) {
00913                         // Collect tile sizes for this layer - optionally converting to deltas
00914                         auto sb = Surface::build_from<uint16_t>();
00915                         sb.generate(num_tiles[plane][loq], 1,
00916                                     [&](unsigned x, unsigned y) -> int16_t { return chunks[idx + x].size(); });
00917                         const Surface sz = sb.finish();
00918 
00919                         // Prefix code and emit them
00920                         b.bytes(EntropyEncoderSizes()
00921                                     .process(sz, entropy_enabled, idx,
00922                                              signaled_configuration.global_configuration.compression_type_size_per_tile)
00923                                     .prefix);
00924                         // Emit tiles
00925                         for (unsigned t = 0; t < num_tiles[plane][loq]; ++t)
00926                             if (chunks[idx + t].size() > 0)
00927                                 b.bytes(chunks[idx + t]);
00928                     }
00929 
00930                     idx += num_tiles[plane][loq];
00931                 }
00932             }
00933         }
00934     }
00935 
00936 #if BITSTREAM_DEBUG
00937     fprintf(goBits, "@@@@ @@@@ encoded_data_tiled >>>> \n");
00938     fflush(goBits);
00939 #endif
00940 }
00941 
00942 void Serializer::emit_additional_info(const AdditionalInfo &additional_info, BitstreamPacker &b) {
00943 #if BITSTREAM_DEBUG
00944     fprintf(goBits, "@@@@ @@@@ additional_info >>>> \n");
00945     fflush(goBits);
00946 #endif
00947 
00948     BitstreamPacker::ScopedContextLabel label(b, "additional_info");
00949 
00950     b.u(8, additional_info.additional_info_type, "additional_info_type");
00951     if (additional_info.additional_info_type == 0) {
00952         b.u(8, additional_info.payload_type, "payload_type");
00953         INFO("SeiPayload");
00954     } else if (additional_info.additional_info_type == 1) {
00955         INFO("VuiParameters");
00956     } else {
00957         // (additional_info.additional_info_type >= 2)
00958         INFO("additional_info_type MUST be 0 or 1 - type = %4d", additional_info.additional_info_type);
00959         CHECK(0);
00960     }
00961 
00962 #if BITSTREAM_DEBUG
00963     fprintf(goBits, "@@@@ @@@@ additional_info <<<< \n");
00964     fflush(goBits);
00965 #endif
00966 }
